const SPOTS={rain:'站台广播漏了一拍，雨声反而显得更近。',cafe:'咖啡机响得太大，你们等它停了才继续刚才那句话。',orbit:'星环慢慢转过去，扶栏的影子换了一个方向。',club:'音乐隔着门漏出来，走廊里的脚步意外地合拍。',garden:'纸花被风吹得翻了一面，月光照到了没画完的花瓣。',studio:'预览网格还在转，你们却先把注意力挪到窗外。'};
export function appointmentChapter(run,a){
 const previous=run.appointments.filter(b=>b!==a&&b.status==='completed'&&b.cast[0]===a.cast[0]&&b.kind===a.kind&&b.result!=='short');
 const index=Math.min(2,previous.length),last=previous.at(-1);
 let beat=CHAPTERS[a.cast[0]][index];
 if(previous.length>=3){const old=previous[(previous.length-3)%3]?.memento;beat=[`小卡之后 · 第 ${previous.length+1} 次相处`,SMALL_TALK[a.cast[0]][(previous.length-3)%SMALL_TALK[a.cast[0]].length]+'这次你们又想起'+(old?'「'+old.title+'」':'前几次留下的小发现')+'，旧记录没有被重新演一遍。','问问那件小事后来真实发生的变化','交换各自的新发现，不要求再做同一个节目','你们各讲了一处后来真的变过的细节。旧卡仍按原样保存，这次的新话写在独立的小页上。','新发现与旧卡并不相同。你们没有重演最初的相遇，各自给新的一页起了一个很普通的名字。'];}
 const echo=last?.memento?`上次留下的「${last.memento.title}」还在。${['shared','parallel','walk'].includes(last.result)?'这回对方记得轮流带路的那一半，先把选择交回你手里。':'这回对方记得你先听完的那一段，带来了自己后来又想到的小事。'}\n\n`:'';
 return {index,title:beat[0],text:SPOTS[a.world]+'\n\n'+echo+beat[1],labels:beat.slice(2,4),results:beat.slice(4),mementos:[beat[0]+' · 留下的一刻',beat[0]+' · 两种版本']};
}
export function applyAppointmentChapter(run,a,scene){
 const chapter=appointmentChapter(run,a);
 if(a.kind==='photo'){scene.text+='\n\n'+chapter.text;return scene;}
 scene.title=chapter.title;scene.text=chapter.text+(a.kind==='create'?'\n\n这次约好的小练习只用眼前这一段时间，不替代正式项目。':'');
 for(const [i,c] of scene.choices.entries())if(i<2){c.label=chapter.labels[i];c.text=chapter.results[i];c.rel=i===0?{trust:6,affection:6}:{trust:5,affection:5,tension:-2};c.keepsakeTitle=chapter.mementos[i];}
 return scene;
}
export function rememberAppointment(run,a,c){
 if(c.meetMode==='short')return;
 const chapter=appointmentChapter(run,a),i=['shared','parallel','walk'].includes(c.meetMode)?1:0;
 a.memento={title:c.keepsakeTitle||chapter.mementos[i],text:c.text,day:run.day,world:a.world,cast:[...a.cast]};
}
export function validMemento(x){return !x||typeof x.title==='string'&&x.title.length<=160&&typeof x.text==='string'&&x.text.length<=3000&&Number.isInteger(x.day)&&x.day>=1&&x.day<=28&&Object.hasOwn(SPOTS,x.world)&&Array.isArray(x.cast)&&x.cast.length>=1&&x.cast.length<=2&&x.cast.every(id=>Object.hasOwn(CHAPTERS,id));}
